CREATE VIEW current_turns AS SELECT t.*,(SELECT started_at_utc_ms FROM turn_timing_observations o WHERE o.thread_id=t.thread_id AND o.turn_id=t.turn_id ORDER BY observation_id DESC LIMIT 1) AS started_at_utc_ms,(SELECT completed_at_utc_ms FROM turn_timing_observations o WHERE o.thread_id=t.thread_id AND o.turn_id=t.turn_id ORDER BY observation_id DESC LIMIT 1) AS completed_at_utc_ms,(SELECT status FROM turn_status_observations o WHERE o.thread_id=t.thread_id AND o.turn_id=t.turn_id ORDER BY observation_id DESC LIMIT 1) AS status FROM turns t;
